ALTER TABLE public.wheel_rounds ADD COLUMN audience text NOT NULL DEFAULT 'all' CHECK (audience IN ('all','welcome','referral','selected'));
CREATE TABLE public.wheel_recipients (round_id uuid NOT NULL REFERENCES public.wheel_rounds(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(round_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.wheel_recipients TO authenticated;
GRANT ALL ON public.wheel_recipients TO service_role;
ALTER TABLE public.wheel_recipients ENABLE ROW LEVEL SECURITY;
CREATE POLICY recipients_read ON public.wheel_recipients FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY recipients_admin ON public.wheel_recipients FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.wheel_audience_eligible(_mode text,_active boolean,_created timestamptz,_started timestamptz,_referral boolean,_selected boolean,_welcome_claimed boolean) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT COALESCE(_active AND CASE _mode WHEN 'all' THEN true WHEN 'welcome' THEN _created>=_started AND NOT _welcome_claimed WHEN 'referral' THEN _referral WHEN 'selected' THEN _selected ELSE false END,false) $$;
REVOKE ALL ON FUNCTION public.wheel_audience_eligible(text,boolean,timestamptz,timestamptz,boolean,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.wheel_audience_eligible(text,boolean,timestamptz,timestamptz,boolean,boolean,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.wheel_round_eligible(_round_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT public.wheel_audience_eligible(r.audience,p.is_active,p.created_at,r.created_at,EXISTS(SELECT 1 FROM public.profiles child WHERE child.referred_by=p.id AND child.id<>p.id AND child.created_at>=r.created_at),EXISTS(SELECT 1 FROM public.wheel_recipients t WHERE t.round_id=r.id AND t.user_id=p.id),EXISTS(SELECT 1 FROM public.wheel_spins s JOIN public.wheel_rounds wr ON wr.id=s.round_id WHERE s.user_id=p.id AND wr.audience='welcome')) FROM public.wheel_rounds r CROSS JOIN public.profiles p WHERE r.id=_round_id AND p.id=auth.uid()),false) $$;
REVOKE ALL ON FUNCTION public.wheel_round_eligible(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.wheel_round_eligible(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.open_targeted_wheel_round(_audience text,_users uuid[] DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'غير مصرح'; END IF;
IF _audience NOT IN ('all','welcome','referral','selected') THEN RAISE EXCEPTION 'نوع الجولة غير صالح'; END IF;
IF _audience='selected' AND (COALESCE(cardinality(_users),0)=0 OR EXISTS(SELECT 1 FROM unnest(_users) u WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=u AND p.is_active))) THEN RAISE EXCEPTION 'اختر حسابات مفعلة'; END IF;
rid:=public.open_wheel_round();
UPDATE public.wheel_rounds SET audience=_audience WHERE id=rid;
IF _audience='selected' THEN INSERT INTO public.wheel_recipients(round_id,user_id) SELECT rid,u FROM (SELECT DISTINCT unnest(_users) u) t; END IF;
RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.open_targeted_wheel_round(text,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.open_targeted_wheel_round(text,uuid[]) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.spin_reward_wheel(_round_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); r public.wheel_rounds; chosen uuid; v jsonb; prize jsonb; threshold numeric; running numeric:=0; existing public.wheel_spins; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'يرجى تسجيل الدخول'; END IF;
SELECT * INTO r FROM public.wheel_rounds WHERE id=_round_id FOR SHARE;
IF r.id IS NULL THEN RAISE EXCEPTION 'الجولة غير موجودة'; END IF;
PERFORM 1 FROM public.profiles WHERE id=uid AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'العجلة للحسابات المفعلة فقط'; END IF;
SELECT * INTO existing FROM public.wheel_spins WHERE round_id=_round_id AND user_id=uid;
IF existing.id IS NOT NULL THEN RETURN to_jsonb(existing); END IF;
IF NOT r.is_open OR COALESCE((SELECT value FROM public.settings WHERE key='wheel_visible'),'false')<>'true' THEN RAISE EXCEPTION 'العجلة غير متاحة'; END IF;
IF NOT public.wheel_round_eligible(_round_id) THEN RAISE EXCEPTION 'هذه الجولة غير مخصصة لحسابك'; END IF;
SELECT prize_id INTO chosen FROM public.wheel_assignments WHERE round_id=_round_id AND user_id=uid;
IF chosen IS NOT NULL THEN SELECT value INTO prize FROM jsonb_array_elements(r.prizes) WHERE (value->>'id')::uuid=chosen;
ELSE threshold:=random()*100; FOR v IN SELECT value FROM jsonb_array_elements(r.prizes) LOOP running:=running+(v->>'weight')::numeric; IF threshold<running THEN prize:=v; EXIT; END IF; END LOOP; END IF;
IF prize IS NULL THEN RAISE EXCEPTION 'إعداد الجوائز غير مكتمل'; END IF;
INSERT INTO public.wheel_spins(round_id,user_id,prize_id,label,amount) VALUES(_round_id,uid,(prize->>'id')::uuid,prize->>'label',(prize->>'amount')::numeric) RETURNING * INTO existing;
UPDATE public.profiles SET balance=balance+existing.amount WHERE id=uid;
INSERT INTO public.notifications(target_user_id,message) VALUES(uid,'جائزة العجلة: '||existing.label||' — '||existing.amount||' USDT');
RETURN to_jsonb(existing); END $$;